readTextHelper:
async function(files) {
 const jobs=[], result=new Map();
 let batch=[], size=0;
 function flush(){if(batch.length){jobs.push({batch});batch=[];size=0;}}
 for(const f of files){
  if(f.size>100000){flush();for(let at=0;at<f.size;at+=100000)jobs.push({file:f.path,at});}
  else{if(size+f.size>100000)flush();batch.push(f.path);size+=f.size;}
 }
 flush();const segments=new Map();
 for(let start=0;start<jobs.length;start+=8){
  const results=await Promise.allSettled(jobs.slice(start,start+8).map(async job=>{
   let py;
   if(job.batch)py="import json\nfrom pathlib import Path\nfiles="+JSON.stringify(job.batch)+"\nprint(json.dumps([{'path':p,'content':Path(p).read_bytes().decode('utf8')} for p in files],ensure_ascii=False))";
   else py="import json\nfrom pathlib import Path\nprint(json.dumps(Path("+JSON.stringify(job.file)+").read_bytes().decode('utf8')["+job.at+":"+(job.at+100000)+"],ensure_ascii=False))";
   const r=await tools.exec_command({cmd:"python - <<'PY'\n"+py+"\nPY",max_output_tokens:150000,workdir:"/workspace/scratch/bd00e5e24ed2/PDF-Editor-Hdv"});
   if(r.exit_code!==0)throw new Error("Read failed");
   return {job,data:JSON.parse(r.output)};
  }));
  for(const r of results){if(r.status!=='fulfilled')throw r.reason;const {job,data}=r.value;if(job.batch){for(const f of data)result.set(f.path,f.content);}else{if(!segments.has(job.file))segments.set(job.file,[]);segments.get(job.file).push([job.at,data]);}}
 }
 for(const [path,parts] of segments)result.set(path,parts.sort((a,b)=>a[0]-b[0]).map(x=>x[1]).join(''));
 return files.map(f=>({path:f.path,mode:f.mode,type:'blob',content:result.get(f.path)}));
}

uploadBinaryHelper:
async function(f){
 const step=262143,parts=[];
 for(let start=0;start<f.size;start+=step*8){
  const offsets=[];for(let at=start;at<Math.min(f.size,start+step*8);at+=step)offsets.push(at);
  const results=await Promise.allSettled(offsets.map(async at=>{
   const r=await tools.exec_command({cmd:"python - <<'PY'\nimport base64\nwith open("+JSON.stringify(f.path)+",'rb') as file:\n file.seek("+at+")\n print(base64.b64encode(file.read("+step+")).decode(),end='')\nPY",max_output_tokens:220000,workdir:"/workspace/scratch/bd00e5e24ed2/PDF-Editor-Hdv"});
   const expected=4*Math.ceil(Math.min(step,f.size-at)/3);
   if(r.exit_code!==0 || r.output.length!==expected || !/^[A-Za-z0-9+/=]+$/.test(r.output))throw new Error('Invalid binary chunk '+f.path+' at '+at);
   return r.output;
  }));
  for(const r of results){if(r.status!=='fulfilled')throw r.reason;parts.push(r.value);}
 }
 const r=await tools.mcp__codex_apps__github_create_blob({repository_full_name:"hieudang99dd/PDF-Editor-Hdv",encoding:'base64',content:parts.join('')});
 if(r.structuredContent?.sha!==f.sha)throw new Error(f.path+': '+JSON.stringify(r).slice(0,600));
 return {path:f.path,sha:f.sha};
}
